namespace NHAMBS.CoveredBonds

open System.IO
open FSharp.Data

/// Typed view of the CMHC Canadian Covered Bonds Registry.
///
/// The provider reads `schema/cmhc-covered-bonds-registry.provider.schema.json`,
/// a flattened copy of the real Draft 2020-12 schema. The copy is generated by
/// `generate-provider-schemas.fsx` because FSharp.Data's schema reader does not
/// resolve `$ref`. The real schema remains the source of truth and is embedded
/// in this assembly for validation by `RegistrySchema.validate`.
type Registry =
    JsonProvider<
        "",
        Schema="schema/cmhc-covered-bonds-registry.provider.schema.json",
        EmbeddedResource="NHAMBS.CoveredBonds, NHAMBS.CoveredBonds.schema.cmhc-covered-bonds-registry.provider.schema.json"
     >

[<RequireQualifiedAccess>]
module Registry =

    /// Parse JSON that is already known to match the registry schema.
    let parse (json: string) : Registry.Root = Registry.Parse json

    /// Validate JSON against the embedded registry schema, then parse it.
    let parseValidated (json: string) : Result<Registry.Root, ValidationError list> =
        match RegistrySchema.validate json with
        | Error errors -> Error errors
        | Ok _ -> Ok(parse json)

    /// Load one registry file, validate it, and return its typed representation.
    let load (path: string) : Result<Registry.Root, ValidationError list> = File.ReadAllText path |> parseValidated

    /// Load a sequence of registry files. Each result keeps its source path.
    let loadMany (paths: string seq) =
        paths |> Seq.map (fun path -> path, load path) |> Seq.toArray

    /// Load every `*.json` file directly under a directory.
    let loadDirectory (directory: string) =
        Directory.EnumerateFiles(directory, "*.json") |> loadMany

    /// Small projection that is useful when indexing the registry.
    let summary (registry: Registry.Root) =
        {|
            IssuerCount = registry.Issuers.Length
            ActiveCount =
                registry.Issuers
                |> Array.filter (fun issuer -> issuer.Status = "active")
                |> Array.length
            SuspendedCount =
                registry.Issuers
                |> Array.filter (fun issuer -> issuer.Status = "suspended")
                |> Array.length
        |}
